import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from histogram ----
// Seeded synthetic county unemployment rates (%), standing in for the BLS
// unemployment-x.csv used by the source notebook. Mulberry32 PRNG for determinism.
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randomNormal(rng: () => number, mean: number, stdDev: number) {
  const u1 = rng();
  const u2 = rng();
  const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  return mean + z * stdDev;
}

const rng = mulberry32(2016);

const countyUnemploymentRates: number[] = Array.from({ length: 3142 }, () => {
  const rate = randomNormal(rng, 5.4, 2.1);
  return Math.max(0.5, Math.round(rate * 10) / 10);
});

const MARGIN = { top: 16, right: 16, bottom: 36, left: 44 };

/** One number per observation; the chart bins them itself. */
export type Data = number[];

export default function Histogram({ data = countyUnemploymentRates, width }:
  { data?: Data; width: number }) {
  const height = Math.round(width * 0.52);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const bins = useMemo(
    () =>
      d3
        .bin()
        .thresholds(40)
        .value((d: number) => d)(data),
    [data]
  );

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([bins[0].x0 ?? 0, bins[bins.length - 1].x1 ?? 0])
        .range([0, innerWidth]),
    [bins, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(bins, (d) => d.length) ?? 0])
        .range([innerHeight, 0]),
    [bins, innerHeight]
  );

  const xTicks: Tick[] = useMemo(
    () => x.ticks(innerWidth / 80).map((v) => ({ value: d3.format('.0f')(v), offset: x(v) })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: d3.format('.0f')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Histogram of U.S. county unemployment rates">
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {bins.map((d) => {
          const x0 = d.x0 ?? 0;
          const x1 = d.x1 ?? 0;
          return (
            <rect
              key={x0}
              x={x(x0) + 1}
              y={y(d.length)}
              width={Math.max(0, x(x1) - x(x0) - 1)}
              height={innerHeight - y(d.length)}
              fill="var(--accent)"
            />
          );
        })}
      </g>
    </svg>
  );
}
